WITH ValidSubscriptions AS (SELECT *, DATEDIFF(CURRENT_DATE(), start_date) AS days_since_start_date FROM subscriptions WHERE monthly_fee <= 230 AND customer_id = 4), status_summary AS (SELECT status, plan, ROUND(STDDEV(days_since_start_date), 2) AS stddev_days_since_start_date, ROUND(AVG(days_since_start_date), 2) AS avg_days_since_start_date FROM ValidSubscriptions GROUP BY status, plan) SELECT * FROM status_summary WHERE stddev_days_since_start_date < 48 ORDER BY avg_days_since_start_date DESC
